let npcIndex = 0;
const sentence = (text) => /[.!?…]$/.test(text) ? text : `${text}.`;
const admissions = [
  (error) => `Me precipité: ${error}`,
  (error) => `Tardé en reconocer que ${error}`,
  (error) => `Mi primer registro ocultaba que ${error}`,
  (error) => `Convertí una suposición en regla: ${error}`,
  (error) => `La rutina parecía útil, pero ${error}`,
  (error) => `No comprobé a tiempo que ${error}`,
  (error) => `Confundí rapidez con certeza y ${error}`,
  (error) => `El plano no mostraba que ${error}`,
  (error) => `Mi criterio dejó fuera un dato: ${error}`,
  (error) => `Ahora puedo decirlo sin rodeos: ${error}`,
];
const partnerChecks = [
  (pokemon, name) => `${pokemon} comprobó el cambio junto a ${name}`,
  (pokemon, name) => `${name} repitió la prueba mientras ${pokemon} vigilaba el borde`,
  (pokemon, name) => `${pokemon} ya reconoce la señal acordada con ${name}`,
  (pokemon, name) => `Con ${pokemon}, ${name} recorrió la solución desde el otro extremo`,
  (pokemon, name) => `${name} dejó que ${pokemon} confirmara el resultado sin apurarlo`,
  (pokemon, name) => `${pokemon} encontró estable la nueva ruta de ${name}`,
  (pokemon, name) => `${name} y ${pokemon} verificaron que el cambio puede revertirse`,
  (pokemon, name) => `${pokemon} respondió al nuevo criterio que propuso ${name}`,
  (pokemon, name) => `${name} anotó la reacción de ${pokemon} antes de cerrar el registro`,
  (pokemon, name) => `${pokemon} cruzó la zona corregida sin repetir el problema de ${name}`,
];
function N(name, sprite, role, partnerPokemon, want, error, clue, plan, result, future) {
  const index = npcIndex++;
  return {
    name, sprite, role, partnerPokemon,
    motivation: sentence(`Quiere ${want}`),
    conflict: sentence(`Su error anterior fue que ${error}`),
    dialogue: {
      before: [sentence(clue), sentence(admissions[index % admissions.length](error)), sentence(plan)],
      after: [sentence(result), sentence(partnerChecks[index % partnerChecks.length](partnerPokemon, name)), sentence(future)],
    },
    _plan: sentence(plan), _future: sentence(future),
  };
}
