if (specs.length !== 50) throw new Error(`Se esperaban 50 rutas y hay ${specs.length}.`);
function compileSpec(spec, globalIndex) {
  const flag = 783 + globalIndex;
  const variable = 179 + globalIndex;
  const [mechanicName, rules, failureSafe] = spec.mechanic;
  const [question, options] = spec.decision;
  const [item, meaning] = spec.reward;
  const npcs = spec.npcs.map(({ _plan, _future, ...npc }) => npc);
  return {
    tier: 2,
    routeBatch: 8 + Math.floor(globalIndex / 5),
    mapId: spec.mapId,
    flag,
    variable,
    title: spec.title,
    promise: spec.promise,
    objective: spec.objective,
    mechanic: { name: mechanicName, rules, failureSafe },
    npcs,
    decision: {
      question,
      options,
      immediate: spec.npcs.map((npc) => npc._plan),
      later: spec.npcs.map((npc) => npc._future),
    },
    reward: { item, meaning },
    progression: { switchId: flag, decisionVariable: variable, freeReturnMapId: 1001 },
    safety: { bagAlwaysAvailable: true, noForcedBattle: true, existingChallengePreserved: true, baseChallengeExpected: globalIndex < 25, freeReturn: true, rewardOnce: true },
  };
}
for (const [offset, macroCycle] of [[0,4],[25,5]]) {
  const blueprints = specs.slice(offset, offset + 25).map((spec, index) => compileSpec(spec, offset + index));
  const output = { version: 1, macroCycle, tier2Batches: 5, blueprints };
  const target = path.join(ROOT, "content", `atlas_tier2_blueprints_macro${String(macroCycle).padStart(2, "0")}.json`);
  fs.writeFileSync(target, `${JSON.stringify(output, null, 2)}\n`);
  console.log(`Tier 2 macrociclo ${String(macroCycle).padStart(2, "0")}: ${blueprints.length} rutas en ${output.tier2Batches} lotes.`);
}
